import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 7 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"7","title":"Page 7 | Home","prev":"/page/6/","next":"/page/8/","posts":[{"title":"JS中关于深拷贝和浅拷贝","url":"/posts/2022-06-20-deep-copy/","date":"2022-06-20 19:37","tags":["js"],"html":"<p>JS 有基本数据类型和复合数据类型，基本数据类型包括 null，undefined，boolean，number，string，symbol。针对这些数据类型都是值拷贝。复合数据类型包括 object，以及衍生的内置数据类型，Array, Map, Set 等等。默认对复合数据类型的赋值操作都是引用拷贝，就是浅拷贝。</p>\\n<h2 id=\\"json-stringify-实现深拷贝\\" tabindex=\\"-1\\">JSON.stringify 实现深拷贝 <a class=\\"header-anchor\\" href=\\"#json-stringify-实现深拷贝\\" aria-label=\\"Permalink to &quot;JSON.stringify 实现深拷贝&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>一种常用的方式是使用 JSON 接口先转换成字符串再解析成对象。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> myDeepCopy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">parse</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">stringify</span><span style=\\"color:#24292E\\">(myOriginal));</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>虽然 V8 引擎优化了 JSON 的解析速度，但是这种方式还是有一些限制条件的，如果数据中存在 Map, Date 等 JS 内置数据结构就没法正常复制。</p>\\n<h2 id=\\"手动实现-deepclone\\" tabindex=\\"-1\\">手动实现 deepClone <a class=\\"header-anchor\\" href=\\"#手动实现-deepclone\\" aria-label=\\"Permalink to &quot;手动实现 deepClone&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isObject</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">obj</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> any</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> obj </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#D73A49\\"> &#x26;&#x26;</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> obj </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'object'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#005CC5\\"> objectToString</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> Object</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">prototype</span><span style=\\"color:#24292E\\">.toString;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> toTypeString</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">value</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  objectToString.</span><span style=\\"color:#6F42C1\\">call</span><span style=\\"color:#24292E\\">(value);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isMap</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Map</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Map]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isSet</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Set</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#005CC5\\">any</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Set]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isDate</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object Date]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> const</span><span style=\\"color:#6F42C1\\"> isRegExp</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> unknown</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#E36209\\"> val</span><span style=\\"color:#D73A49\\"> is</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#D73A49\\"> =></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  toTypeString</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> '[object RegExp]'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">T</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#E36209\\">val</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#6F42C1\\">isObject</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (Array.</span><span style=\\"color:#6F42C1\\">isArray</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> val.</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(deepClone) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isDate</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Date</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isMap</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Map</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isSet</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Set</span><span style=\\"color:#24292E\\">(val) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isRegExp</span><span style=\\"color:#24292E\\">(val)) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(val.source, val.flags) </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> typeof</span><span style=\\"color:#24292E\\"> val;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> Object.</span><span style=\\"color:#6F42C1\\">keys</span><span style=\\"color:#24292E\\">(val).</span><span style=\\"color:#6F42C1\\">reduce</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">acc</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">key</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    acc[key </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> keyof</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(val[key </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#D73A49\\"> keyof</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> acc;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, {} </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#6F42C1\\"> T</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br></div></div><p>手动实现 deepClone 可以处理 Date, Map, Set, RegExp 这些数据结构，但这也不是完美的解决方案，例如二进制的数据结构 <code>ArrayBuffer</code> 就没在处理范围，但对于绝大多数场景也足够用了。</p>\\n<h2 id=\\"使用-structuredclone\\" tabindex=\\"-1\\">使用 structuredClone <a class=\\"header-anchor\\" href=\\"#使用-structuredclone\\" aria-label=\\"Permalink to &quot;使用 structuredClone&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> myDeepCopy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> structuredClone</span><span style=\\"color:#24292E\\">(myOriginal);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最新的浏览器标准添加了 <code>structuredClone</code> 函数，可以实现常见数据结构的复制，但是有些数据结构也是不能复制的，例如 <code>Function</code>。不过 Function 也没有复制的必要。\\n由于这个函数最近才添加，实际使用中可能还需要搭配 <a href=\\"https://github.com/zloirock/core-js#structuredclone\\" target=\\"_blank\\" rel=\\"noreferrer\\">polyfill</a>。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>实际开发工作中大家可以根据自己的需要选择合适的深拷贝解决方案。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/structuredClone\\" target=\\"_blank\\" rel=\\"noreferrer\\">structuredClone</a></p>\\n<p><a href=\\"https://web.dev/structured-clone/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Deep-copying in JavaScript using structuredClone</a></p>\\n<p><a href=\\"https://lodash.com/docs/4.17.15#cloneDeep\\" target=\\"_blank\\" rel=\\"noreferrer\\">cloneDeep</a></p>\\n"},{"title":"如何实现虚拟滚动条","url":"/posts/2022-05-12-virtual-scroll/","date":"2022-05-12 19:25","tags":["web"],"html":"<p>最近在做UI组件，发现下拉组件经常会有很多选项导致渲染的DOM过多，在低性能的设备上交互变的很卡。例如最常见的需求就是下拉选择所在国家或者地区，全世界有两百多个国家或者地区。\\n如果把所有国家或者地区都渲染出来必然会导致DOM过多，在低性能设备上滚动起来都会很卡。这时候就需要使用虚拟滚动条来提高渲染性能。</p>\\n<h2 id=\\"虚拟滚动条原理\\" tabindex=\\"-1\\">虚拟滚动条原理 <a class=\\"header-anchor\\" href=\\"#虚拟滚动条原理\\" aria-label=\\"Permalink to &quot;虚拟滚动条原理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>虚拟滚动的原理是显示的容器高度固定，我们只渲染用户看到的选项。但是选项容器的高度还是设置成所有选项的高度，这样滚动条效果保持一样，不过实际渲染的DOM数量却大大减少。</p>\\n<h2 id=\\"虚拟滚动条的数学计算\\" tabindex=\\"-1\\">虚拟滚动条的数学计算 <a class=\\"header-anchor\\" href=\\"#虚拟滚动条的数学计算\\" aria-label=\\"Permalink to &quot;虚拟滚动条的数学计算&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前虚拟滚动的主要限制是需要知道显示容器的高度，渲染的每个选项的高度以及渲染的选项的数量。我们可以通过用户的滚动距离来计算需要显示的内容以及需要偏移的距离。</p>\\n<p>细节请参考下面的代码：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> VirtualScroll</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IVirtualScrollProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  itemCount, </span><span style=\\"color:#6A737D\\">// 选项的数量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  height, </span><span style=\\"color:#6A737D\\">// 显示容器的高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  childHeight, </span><span style=\\"color:#6A737D\\">// 选项的高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  itemData </span><span style=\\"color:#6A737D\\">// 选项元素</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> wrapperRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLDivElement</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 得高容器滚动了多少距离</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> scrollTop</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useScrollAware</span><span style=\\"color:#24292E\\">(wrapperRef);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 计算渲染的选项的总高度</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> totalHeight</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> childHeight </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> itemCount,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [childHeight, itemCount]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据滚动距离，计算要渲染的选项的起始位置</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> startIndex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> Math.</span><span style=\\"color:#6F42C1\\">floor</span><span style=\\"color:#24292E\\">(scrollTop </span><span style=\\"color:#D73A49\\">/</span><span style=\\"color:#24292E\\"> childHeight),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [scrollTop, childHeight]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据容器的高度计算要渲染的选项的数量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> visibleItemCount</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> Math.</span><span style=\\"color:#6F42C1\\">ceil</span><span style=\\"color:#24292E\\">(height </span><span style=\\"color:#D73A49\\">/</span><span style=\\"color:#24292E\\"> childHeight),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [height, childHeight]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 根据渲染的选项的起始位置，计算选项的偏移量</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> offsetY</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> startIndex </span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\"> childHeight,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [childHeight, startIndex]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">  // 计算实际显示的选项元素</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> visibleItemData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useMemo</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> itemData.</span><span style=\\"color:#6F42C1\\">slice</span><span style=\\"color:#24292E\\">(startIndex, startIndex </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#24292E\\"> visibleItemCount);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [itemData, startIndex, visibleItemCount]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        height,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        overflow: </span><span style=\\"color:#032F62\\">'auto'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{wrapperRef}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          position: </span><span style=\\"color:#032F62\\">'relative'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          overflow: </span><span style=\\"color:#032F62\\">'hidden'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          willChange: </span><span style=\\"color:#032F62\\">'transform'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          height: totalHeight</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">div</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            willChange: </span><span style=\\"color:#032F62\\">'transform'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            transform: </span><span style=\\"color:#032F62\\">\`translate3d(0, \${</span><span style=\\"color:#24292E\\">offsetY</span><span style=\\"color:#032F62\\">}px, 0)\`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        ></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          {visibleItemData}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> default</span><span style=\\"color:#6F42C1\\"> memo</span><span style=\\"color:#24292E\\">(VirtualScroll);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br><span class=\\"line-number\\">62</span><br><span class=\\"line-number\\">63</span><br><span class=\\"line-number\\">64</span><br></div></div><p>完整的实现请参考 <a href=\\"https://github.com/acgotaku/simple-ui/blob/master/src/components/Select/VirtualRow.tsx\\" target=\\"_blank\\" rel=\\"noreferrer\\">Simple UI - Select</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在知道虚拟滚动条的原理之后，发现并不难实现，重点要理解几个数值的计算，才能明白为什么这样能达到预期的效果。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://dev.to/adamklein/build-your-own-virtual-scroll-part-i-11ib\\" target=\\"_blank\\" rel=\\"noreferrer\\">Build your Own Virtual Scroll</a></p>\\n"},{"title":"Mac M1系统配置C++环境","url":"/posts/2022-04-13-m1-cpp/","date":"2022-04-13 20:03","tags":["C++"],"html":"<p>最近在学习计算机图形学，需要配置C++环境和opencv来编译作业代码，于是我就开始折腾下M1如何编译C++代码了。</p>\\n<h2 id=\\"安装依赖\\" tabindex=\\"-1\\">安装依赖 <a class=\\"header-anchor\\" href=\\"#安装依赖\\" aria-label=\\"Permalink to &quot;安装依赖&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先你需要安装Mac下的包管理器 <a href=\\"https://brew.sh/\\" target=\\"_blank\\" rel=\\"noreferrer\\">homebrew</a>，官网有详细的安装教程，我就不赘述了。</p>\\n<p>接下来安装C++相关的依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> gcc</span><span style=\\"color:#032F62\\"> cmake</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后是图形学相关的依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> eigen</span><span style=\\"color:#032F62\\"> opencv</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"配置头文件路径\\" tabindex=\\"-1\\">配置头文件路径 <a class=\\"header-anchor\\" href=\\"#配置头文件路径\\" aria-label=\\"Permalink to &quot;配置头文件路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<blockquote>\\n<p>This script installs Homebrew to its preferred prefix (/usr/local for macOS Intel, /opt/homebrew for Apple Silicon and /home/linuxbrew/.linuxbrew for Linux) so that you don’t need sudo when you brew install.</p>\\n</blockquote>\\n<p>homebrew 官网有描述M1的安装路径更改到 <code>/opt/homebrew</code> 了。所以我们需要指定头文件路径，这里我们指定到 <code>/opt/homebrew/include</code>。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> CPATH</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">/opt/homebrew/include</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#24292E\\"> LIBRARY_PATH</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">/opt/homebrew/lib</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>把上述代码添加到 <code>.bashrc</code> 文件，如果你使用的是 zsh 请添加到 <code>.zshrc</code> 文件。</p>\\n<h2 id=\\"检测头文件路径\\" tabindex=\\"-1\\">检测头文件路径 <a class=\\"header-anchor\\" href=\\"#检测头文件路径\\" aria-label=\\"Permalink to &quot;检测头文件路径&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">gcc</span><span style=\\"color:#005CC5\\"> -x</span><span style=\\"color:#032F62\\"> c++</span><span style=\\"color:#005CC5\\"> -v</span><span style=\\"color:#005CC5\\"> -E</span><span style=\\"color:#032F62\\"> /dev/null</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>如果输出结果有 <code>/opt/homebrew/include</code> 就说明配置成功了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>配置环境看似简单，但找到解决方案需要花不少时间，这里主要问题是M1下安装路径不同，所以我们需要指定头文件路径。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://apple.stackexchange.com/questions/414622/installing-a-c-c-library-with-homebrew-on-m1-macs\\" target=\\"_blank\\" rel=\\"noreferrer\\">Installing a C/C++ library with homebrew on M1 Macs</a></p>\\n<p><a href=\\"https://zhuanlan.zhihu.com/p/371245964\\" target=\\"_blank\\" rel=\\"noreferrer\\">在 Mac OS 下配置 GAMES101 开发环境</a></p>\\n<p><a href=\\"https://stackoverflow.com/questions/19852199/view-default-include-path-of-c-headers-in-mac-os-x-by-gcc-v\\" target=\\"_blank\\" rel=\\"noreferrer\\">View default include path of C headers in Mac OS X by gcc -v?</a></p>\\n"}]},"relativePath":"page/7/index.md","filePath":"page/[page].md"}`),l={name:"page/7/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
